#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, NR, NQ, NP, ...)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout  = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);
		auto np_len = A | get_length<'p'>();

		A[state] = static_cast<num_t>(((r * q + p) % np_len))
			/ static_cast<num_t>(np_len);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		auto np_len = C4 | get_length<'p'>();

		C4[state] = static_cast<num_t>(((s * p) % np_len))
			/ static_cast<num_t>(np_len);
	});
}

// computation kernel
//
// Original C-like semantics (PolyBench doitgen):
//   for (r)
//     for (q) {
//       for (p) {
//         sum[p] = 0;
//         for (s)
//           sum[p] += A[r][q][s] * C4[s][p];
//       }
//       for (p)
//         A[r][q][p] = sum[p];
//     }
//
// This computes, for each (r,q,p):
//   A[r][q][p] = sum_{s} A_old[r][q][s] * C4[s][p]
//
// The implementation below preserves this computation but
// reorganizes the inner loops to improve locality:
//
//   for (r,q):
//     for (p) sum[p] = 0;
//     for (s) {
//       a = A[r,q,s];                // load once
//       for (p) sum[p] += a * C4[s,p];
//     }
//     for (p) A[r,q,p] = sum[p];
//
// Key effects:
//   - A[r,q,s] is loaded once per s and reused across all p.
//   - C4[s,p] and sum[p] are traversed with unit stride in p.
//   - All loop nests are expressed via Noarr traversers.
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Create a view of A in which its fastest dimension is named 's'
	// instead of 'p'. This makes the reduction index explicit while
	// preserving the physical layout (no data is moved).
	auto A_as_s = A ^ noarr::rename<'p', 's'>();

#pragma scop
	// Traverse independent (r,q) "planes" of A. C4 is read-only and
	// sum is a scratch buffer reused for each (r,q).
	noarr::traverser(A, A_as_s, C4, sum).template for_dims<'r', 'q'>([=](auto trav_rq) {
		// -----------------------------------------------------------------
		// 1. Initialize the accumulation buffer sum[p] for this (r,q):
		//    for p: sum[p] = 0;
		// We use trav_rq.for_dims<'p'> so that the state contains (r,q,p),
		// which we can pass both to A and sum (sum ignores r,q).
		// -----------------------------------------------------------------
		trav_rq.template for_dims<'p'>([=](auto trav_p) {
			auto state_rqp = trav_p.state(); // contains r, q, p
			sum[state_rqp] = static_cast<num_t>(0);
		});

		// -----------------------------------------------------------------
		// 2. Accumulate over s:
		//
		//    for s:
		//      a_rqs = A[r,q,s];
		//      for p:
		//        sum[p] += a_rqs * C4[s,p];
		//
		// We hoist 's' to be outer-most in this (r,q) slice so that:
		//   - A[r,q,s] is loaded once per s and reused across all p.
		//   - C4[s,p] and sum[p] are traversed contiguously in p.
		// -----------------------------------------------------------------
		auto trav_rq_s_outer = trav_rq.order(noarr::hoist<'s'>());

		trav_rq_s_outer.template for_dims<'s'>([=](auto trav_s) {
			// Fixed indices r, q, s for this slice
			auto state_rqs = trav_s.state(); // has r, q, s
			num_t a_rqs = A_as_s[state_rqs]; // A[r][q][s] (via renamed view)

			// For this (r,q,s), iterate all p (fastest dimension).
			trav_s.for_each([=](auto state) {
				// state has r, q, s, p; sum and C4 only use relevant dims.
				sum[state] += a_rqs * C4[state];
			});
		});

		// -----------------------------------------------------------------
		// 3. Write back the final result:
		//    for p: A[r,q,p] = sum[p];
		// -----------------------------------------------------------------
		trav_rq.template for_dims<'p'>([=](auto trav_p) {
			auto state_rqp = trav_p.state(); // r, q, p
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
