#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
constexpr auto A_layout  = p_vec ^ q_vec ^ r_vec; // A[r][q][p]
constexpr auto C4_layout = p_vec ^ s_vec;         // C4[s][p]
constexpr auto sum_layout = p_vec;                // sum[p]

// initialization function
void init_array(auto A, auto C4) {
	using namespace noarr;

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);
		auto np_len = A | get_length<'p'>();

		A[state] = static_cast<num_t>(((r * q + p) % np_len))
			/ static_cast<num_t>(np_len);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);
		auto np_len = C4 | get_length<'p'>();

		C4[state] = static_cast<num_t>(((s * p) % np_len))
			/ static_cast<num_t>(np_len);
	});
}

// computation kernel
//
// Original (naive) semantics in C-like pseudocode:
//
//   for (r)
//     for (q) {
//       for (p) {
//         sum[p] = 0;
//         for (s)
//           sum[p] += A[r][q][s] * C4[s][p];
//       }
//       for (p)
//         A[r][q][p] = sum[p];
//     }
//
// This loads A[r][q][s] NP times (once per p), and walks C4[s][p] with a
// large stride in memory.
//
// The optimized kernel below keeps the *same mathematical result* but
// restructures the loops to:
//
//   for (r, q):
//     for (p): sum[p] = 0;
//     for (s):
//       a = A[r][q][s];              // load once per s
//       for (p): sum[p] += a * C4[s][p];
//     for (p): A[r][q][p] = sum[p];
//
// Properties:
//   - For each (r, q, p), the accumulation over s still happens in
//     increasing s-order, so floating-point results are bitwise identical.
//   - A[r][q][s] is now loaded once per s (not once per (s, p)).
//   - C4[s][p] and sum[p] are traversed with unit stride in p.
//   - We additionally block p using into_blocks_dynamic to help cache/SIMD.
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Tile size along p (output / C4 column dimension).
	// This does not change semantics; it only affects traversal order.
	// into_blocks_dynamic correctly handles the case NP % tile_p != 0
	// via a guard dimension, so no elements are skipped or duplicated.
	constexpr std::size_t tile_p = 32;

	// Block the p-dimension in C4 and sum:
	//   - C4_blocked has dims: 's' (rows), 'P' (p-block), 'p' (in-block), 't' (presence guard)
	//   - sum_blocked has dims: 'P', 'p', 't'
	// They are just different *views* on the same underlying memory (layout preserved).
	auto C4_blocked  = C4  ^ noarr::into_blocks_dynamic<'p', 'P', 'p', 't'>(tile_p);
	auto sum_blocked = sum ^ noarr::into_blocks_dynamic<'p', 'P', 'p', 't'>(tile_p);

#pragma scop
	// Traverse all (r, q) planes of A. Each (r, q) slice is independent and
	// reuses the same 1D buffer sum[p].
	noarr::traverser(A).template for_dims<'r', 'q'>([&](auto trav_rq) {
		// Extract current (r, q) indices
		auto rq_state = trav_rq.state();
		auto r_idx = noarr::get_index<'r'>(rq_state);
		auto q_idx = noarr::get_index<'q'>(rq_state);

		// Create a 1D view A_rq[p] = A[r_idx][q_idx][p].
		// This fixes the outer dimensions and leaves only 'p'.
		auto A_rq = A ^ noarr::fix<'r', 'q'>(r_idx, q_idx);

		// -------------------------------------------------------------------
		// 1) Initialize sum[p] = 0 for this (r, q).
		//    We use the blocked view; every valid p appears exactly once.
		// -------------------------------------------------------------------
		noarr::traverser(sum_blocked).for_each([&](auto state_Ppt) {
			sum_blocked[state_Ppt] = static_cast<num_t>(0);
		});

		// -------------------------------------------------------------------
		// 2) Accumulate over s:
		//
		//    for (s)
		//      a = A[r,q,s];
		//      for (p-block P, p in P)
		//        sum[p] += a * C4[s,p];
		//
		//    For each fixed (r,q,s) we:
		//      - load a_rqs once (contiguous access along A_rq[p]),
		//      - update all p in tiles; both sum and C4 are accessed
		//        contiguously along p inside each tile.
		// -------------------------------------------------------------------
		noarr::traverser(C4_blocked, sum_blocked).template for_dims<'s'>([&](auto trav_s) {
			// trav_s has 's' fixed, remaining dims: 'P', 'p', 't'
			auto s_state = trav_s.state();
			auto s_idx = noarr::get_index<'s'>(s_state);

			// Load A[r,q,s] once for this s and (r,q) slice.
			const num_t a_rqs = A_rq[noarr::idx<'p'>(s_idx)];

			// Iterate all (P, p, t) for the current s. The guard dim 't'
			// ensures that for incomplete tiles (near the end) only valid
			// p-indices are visited.
			trav_s.for_each([&](auto state) {
				// state has dims: 's', 'P', 'p', 't'
				//   - C4_blocked[state]   == C4[s][p]
				//   - sum_blocked[state]  == sum[p]
				sum_blocked[state] += a_rqs * C4_blocked[state];
			});
		});

		// -------------------------------------------------------------------
		// 3) Write the accumulated result back to A[r,q,p].
		//    At this point sum[p] holds:
		//       sum[p] = Σ_s A[r,q,s] * C4[s,p]
		//    and we store it into A[r,q,p].
		// -------------------------------------------------------------------
		noarr::traverser(sum).for_each([&](auto p_state) {
			auto p_idx = noarr::get_index<'p'>(p_state);
			A_rq[noarr::idx<'p'>(p_idx)] = sum[p_state];
		});
	});
#pragma endscop
